import json, sys
BASE = "https://freya-bank-mock-team.egemenayrac.workers.dev/v1"
HDR = {"type": "object", "properties": {"Content-Type": {"type": "string", "default": "application/json"}}}

HOLS = "['2026-10-26','2026-11-11','2026-11-26','2026-12-25','2027-01-01']"

COMMON = r'''
import datetime, json
HOL = set(%s)
AY = ['', 'Ocak','Şubat','Mart','Nisan','Mayıs','Haziran','Temmuz','Ağustos','Eylül','Ekim','Kasım','Aralık']
GUN = ['Pazartesi','Salı','Çarşamba','Perşembe','Cuma','Cumartesi','Pazar']
def isbd(d):
    return d.weekday() < 5 and d.isoformat() not in HOL
def nextbd(d):
    d = d + datetime.timedelta(days=1)
    while not isbd(d):
        d = d + datetime.timedelta(days=1)
    return d
def tr(d):
    return str(d.day) + ' ' + AY[d.month] + ' ' + str(d.year) + ' ' + GUN[d.weekday()]
def para(x):
    x = round(float(x) + 1e-9, 2)
    lira = int(x)
    kurus = int(round((x - lira) * 100))
    return (str(lira) + ' lira' + ((' ' + str(kurus) + ' kuruş') if kurus else ''))
def today_now():
    n = str(vars.get('now') or '')
    try:
        dt = datetime.datetime.fromisoformat(n[:16])
    except Exception:
        dt = datetime.datetime(2026, 10, 14, 11, 0)
    return dt
''' % HOLS

INIT = COMMON + r'''
try:
    dt = today_now()
    t = dt.date()
    vars['hitap'] = str(vars.get('first_name') or '') + (' Hanım' if str(vars.get('title') or '') == 'Ms' else ' Bey')
    lines = []
    hm = dt.strftime('%H:%M')
    if isbd(t) and hm < '19:00':
        lines.append('Bugün ' + tr(t) + ' (' + t.isoformat() + '): saat ' + hm + ' sonrası ile 19:00 arası olur.')
    else:
        lines.append('Bugün ' + tr(t) + ': geri arama için uygun değil.')
    nb = nextbd(t)
    lines.append('Bir sonraki iş günü ' + tr(nb) + ' (' + nb.isoformat() + '): 10:00 ile 19:00 arası (ikisi dahil) olur.')
    lines.append('Bunların dışındaki her gün ve saat olmaz. Yarın = ' + tr(t + datetime.timedelta(days=1)) + '.')
    vars['callback_table'] = '\n'.join(lines)
except Exception:
    vars['hitap'] = str(vars.get('first_name') or '')
    vars['callback_table'] = 'Geri arama bugün ya da bir sonraki iş günü 10:00-19:00 arası olabilir.'
'''

COMPUTE = COMMON + r'''
try:
    dt = today_now(); t = dt.date()
    prods = vars.get('acct_json') or vars.get('products')
    if isinstance(prods, str):
        try:
            prods = json.loads(prods)
        except Exception:
            prods = None
    p = prods[0] if isinstance(prods, list) and prods else {}
    if not p:
        p = {}
        for k in ['product_id','type','card_last4','past_due','days_late','minimum_payment','instalment_amount']:
            for key in ['products.0.' + k, 'get_account_response.data.products.0.' + k]:
                if vars.get(key) is not None:
                    p[k] = vars.get(key)
    typ = str(p.get('type') or '')
    full = float(p.get('past_due') or 0)
    dl = int(float(p.get('days_late') or 0))
    if typ == 'credit_card':
        floor = float(p.get('minimum_payment') or 0)
        pname = str(p.get('card_last4') or '') + ' ile biten kredi kartınız'
    elif typ == 'car_loan':
        floor = float(p.get('instalment_amount') or 0); pname = 'taşıt krediniz'
    else:
        floor = float(p.get('instalment_amount') or 0); pname = 'ihtiyaç krediniz'
    late = dl >= 8
    n = 7 if late else 12
    d = t; c = 0
    while c < n:
        d = d + datetime.timedelta(days=1)
        if isbd(d):
            c += 1
    deadline = d
    vars['product_id'] = str(p.get('product_id') or 'p1')
    vars['product_name'] = pname
    vars['full_amount'] = str(round(full, 2)); vars['floor_amount'] = str(round(floor, 2))
    vars['full_tr'] = para(full); vars['floor_tr'] = para(floor)
    vars['days_late'] = str(dl)
    vars['deadline_iso'] = deadline.isoformat(); vars['deadline_tr'] = tr(deadline)
    vars['band'] = 'late' if late else 'early'
    vars['max_attempts'] = '2' if late else '1'
    # this week's last business day
    monday = t - datetime.timedelta(days=t.weekday())
    def lastbd(mon):
        for i in range(4, -1, -1):
            x = mon + datetime.timedelta(days=i)
            if isbd(x):
                return x
        return None
    lw = lastbd(monday)
    if lw is None or lw <= t:
        lw = lastbd(monday + datetime.timedelta(days=7))
    vars['offer1_date_tr'] = tr(lw); vars['offer1_date_iso'] = lw.isoformat()
    rows = []
    x = t
    end = deadline + datetime.timedelta(days=21)
    while x <= end:
        s = x.isoformat() + ' ' + tr(x) + ': '
        if x > deadline:
            s += 'son tarihten sonra -> "Kaydedebileceğim en geç tarih ' + tr(deadline) + '." de ve ' + tr(deadline) + ' öner.'
        elif not isbd(x):
            nb = nextbd(x)
            if nb > deadline:
                s += 'iş günü değil -> en geç tarih ' + tr(deadline) + ', onu öner.'
            else:
                s += ('banka tatili' if x.weekday() < 5 else 'hafta sonu') + ' -> kabul etme, bir sonraki iş günü ' + tr(nb) + ' öner.'
        else:
            s += 'uygun, kabul edilebilir.'
        rows.append(s)
        x = x + datetime.timedelta(days=1)
    rel = ['bugün = ' + tr(t), 'yarın = ' + tr(t + datetime.timedelta(days=1)), 'öbür gün = ' + tr(t + datetime.timedelta(days=2))]
    for i in range(7):
        rel.append('bu ' + GUN[i] + ' = ' + tr(monday + datetime.timedelta(days=i)))
        rel.append('haftaya ' + GUN[i] + ' = ' + tr(monday + datetime.timedelta(days=7 + i)))
    rel.append('bu hafta sonu / hafta sonu = ' + tr(monday + datetime.timedelta(days=5)))
    vars['date_table'] = '\n'.join(rows)
    vars['rel_table'] = '\n'.join(rel)
    vars['attempts_used'] = '0'
    vars['acct_state'] = 'ok' if full > 0 else 'missing'
except Exception as e:
    vars['acct_state'] = 'missing'
    vars['date_table'] = ''; vars['rel_table'] = ''
'''

CHECK = COMMON + r'''
try:
    t = today_now().date()
    full = float(vars.get('full_amount') or 0); floor = float(vars.get('floor_amount') or 0)
    deadline = datetime.date.fromisoformat(str(vars.get('deadline_iso')))
    pd = str(vars.get('proposed_date') or '')[:10]
    try:
        d = datetime.date.fromisoformat(pd)
    except Exception:
        d = None
    try:
        a = float(str(vars.get('proposed_amount') or '').replace(',', '.'))
    except Exception:
        a = full
    if a > full + 0.001 or a <= 0:
        a = full
    a = round(a, 2)
    msg = ''
    if d is None:
        msg = 'Müşteriden kesin bir gün iste.'
    elif d < t:
        msg = 'Geçmiş bir tarih kaydedilemez. Söyle: "Bugün ya da ileri bir tarih olmalı." ve ' + tr(t) + ' öner.'
    elif d > deadline:
        msg = 'Müşteriye söyle: "Kaydedebileceğim en geç tarih ' + tr(deadline) + '." ve bu tarihi öner. Müşteri bunu reddederse kesin ret sayılır.'
    elif not isbd(d):
        nb = nextbd(d)
        if nb > deadline:
            nb = deadline
        msg = 'Söyle: "' + tr(d) + ' iş günü değil, ' + tr(nb) + ' olabilir mi?" ve bu tarihi öner.'
    elif a < floor - 0.001:
        msg = 'Söyle: "' + para(a) + ' kaydedilemez, en az ' + para(floor) + ' ödemeniz gerekiyor; kalan tutar gecikmede kalır." ve ' + para(floor) + ' öner (yalnızca bir kez). Müşteri reddederse kesin ret sayılır.'
    if msg:
        vars['verdict'] = 'offer_other'
        vars['check_msg'] = msg
        vars['agreed'] = 'no'
    else:
        vars['verdict'] = 'ok'
        vars['check_msg'] = ''
        vars['promise_date'] = d.isoformat(); vars['promise_amount'] = str(a)
        vars['confirm_text'] = vars.get('product_name', '') + ' için ' + para(a) + ' tutarındaki ödemeyi ' + tr(d) + ' günü yapacaksınız.'
        vars['agreed'] = 'no'
except Exception:
    vars['verdict'] = 'offer_other'; vars['check_msg'] = 'Tarihi ve tutarı yeniden sor.'; vars['agreed'] = 'no'
'''

POST_GENERIC = r'''
try:
    if isinstance(result, dict):
        result.pop('header', None)
        d = result.get('data')
        sc = result.get('status_code')
        if not isinstance(d, dict) or (isinstance(sc, int) and sc >= 400) or d.get('ok') is False:
            err = d.get('error') if isinstance(d, dict) else ''
            result['data'] = {'ok': False, 'error': str(err or 'servis hatası'), 'what_to_do_next': '%s'}
        else:
            d['what_to_do_next'] = '%s'
except Exception:
    pass
'''

VERIFY_POST = r'''
try:
    if isinstance(result, dict):
        result.pop('header', None)
        d = result.get('data')
        sc = result.get('status_code')
        if not isinstance(d, dict) or (isinstance(sc, int) and sc >= 500):
            result['data'] = {'ok': False, 'what_to_do_next': 'Servis hatası, cevap sayılmadı. Aynı cevapla verify_identity aracını bir kez daha çağır.'}
        elif d.get('hint') == 'day_month_swapped':
            d['what_to_do_next'] = 'Gün ve ay karışmış olabilir. Müşteriden doğum tarihini ayı kelimeyle söyleyerek tekrar etmesini iste. Bu yanlış cevap sayılmaz.'
        elif d.get('ok') is False:
            d['what_to_do_next'] = 'Cevap okunamadı (yanlış sayılmadı). Müşteriden aynı soruyu net olarak tekrar iste.'
        elif str(d.get('all_verified')).lower() == 'true':
            d['what_to_do_next'] = 'Kimlik doğrulandı.'
        elif str(d.get('verified')).lower() == 'true':
            d['what_to_do_next'] = 'Bu cevap doğru. Şimdi bir sonraki güvenlik sorusunu sor (telefon numarasının son dört hanesi).'
        else:
            left = d.get('wrong_answers_left')
            try:
                left = int(left)
            except Exception:
