def code_node(name, code, transitions):
    return {"name": name, "node_type": "code", "passthrough": True,
            "passthrough_default_transition": transitions[-1]["target_node"],
            "on_enter": {"type": "silent"},
            "pre_actions": [{"type": "function", "function": {"name": "code_exec", "handler": "__function__:code_exec",
                "parameters": {"type": "object", "properties": {"code": {"type": "string", "default": code},
                                                               "timeout_ms": {"type": "number", "default": 20000}}}}}],
            "transitions": transitions}

def always(t):
    return {"target_node": t, "description": "always", "condition": {"operator": "always"}}

def eq(var, val, t, desc):
    return {"target_node": t, "description": desc, "condition": {"logic": "or", "conditions": [{"variable": var, "operator": "equals", "operand": val}]}}

def isset(var, t, desc):
    return {"target_node": t, "description": desc, "condition": {"logic": "or", "conditions": [{"variable": var, "operator": "is_set"}]}}

def conv(name, task, tools, transitions, on_enter, extraction=None, first_only=False):
    n = {"name": name, "node_type": "conversation", "task_message": task, "tools": tools,
         "transitions": transitions, "on_enter": on_enter, "max_node_turns": 60,
         "extraction_schema": extraction or [], "on_enter_first_entry_only": first_only,
         "interruptible": True}
    return n

def end_node(name):
    return {"name": name, "node_type": "end_call", "on_enter": {"type": "silent"}, "disable_inactivity_monitor": True,
            "transitions": [], "terminal": {"type": "function", "function": {"name": name, "handler": "__function__:end_call",
            "parameters": {"type": "object", "properties": {"message_mode": {"type": "string", "default": "none"}}}}}}

def api_node(name, tts, tool, transitions, mapping=None):
