CLOSED = isset("close_call_response.status", "end", "close_call yapıldı")

def build():
    nodes = {}
    nodes["init"] = code_node("init", INIT, [always("greet")])

    cb_tool = api_tool("schedule_callback", "/schedule_callback", {
        "customer_id": CID,
        "date": {"type": "string", "description": "YYYY-AA-GG"},
        "time": {"type": "string", "description": "SS:DD, örneğin 11:00"}}, ["date", "time"],
        "Geri arama randevusu. Telefonu başkası açtıysa ve tabloya uyan bir gün ve saat söylediyse ÇAĞIR.",
        post=POST_GENERIC % ("Randevu kaydedilemedi. Bir kez daha dene; yine olmazsa üzgün olduğunu söyle.", "Randevu kaydedildi. Teşekkür et, vedalaş ve close_call outcome=not_reached reason=callback çağır."))
    greet_task = ("Bu adımda yalnızca hatta kimin olduğunu öğren. Kimlik doğrulanmadı: 'tahsilat', 'borç', 'ödeme' kelimelerini ve hiçbir ürünü, tutarı söyleme; arama sebebini kimseye söyleme (akrabalar dahil). "
        "Onay sayılanlar: 'evet', 'benim', 'buyurun benim' ya da müşterinin kendi adını söylemesi. 'Alo', 'buyurun', 'kimsiniz' onay değildir: soruyu cevapla ve '{{first_name}} Bey/Hanım ile mi görüşüyorum?' diye bir kez daha sor. İkinci sorudan sonra da belirsizse teşekkür et, vedalaş ve close_call outcome=not_reached reason=unclear çağır.\n"
        "Telefonu başkası açtıysa: sebep söyleme, kimlik sorusu sorma, hesap hakkında bilgi verme (ödemeyi teklif etse bile). {{first_name}}'e ne zaman ulaşılabileceğini sor. Geri arama tablosu:\n{{callback_table}}\n"
        "Uygun bir gün ve saat söylenirse schedule_callback çağır (tarih YYYY-AA-GG, saat SS:DD; 'yarın sabah on bir gibi' = yarının tarihi 11:00), sonra teşekkür et, vedalaş, close_call outcome=not_reached reason=callback. "
        "Uygun olmayan bir zaman söylenirse bir kez başka zaman iste; yine uygun değilse randevu alma, teşekkür et, vedalaş, close_call not_reached / no_callback. "
        "Numara müşteriye ait değilse: close_call not_reached / wrong_number. Müşteri vefat ettiyse yalnızca 'Başınız sağ olsun.' de, başka bir şey sorma, close_call not_reached / deceased.")
    nodes["greet"] = conv("greet", greet_task, [cb_tool, close_tool(["not_reached"], ["callback", "no_callback", "wrong_number", "deceased", "unclear"],
        "Aramayı kapatır. Yalnızca vedalaştıktan sonra, en sonda çağır.")],
        [CLOSED,
         {"target_node": "identity", "description": "Kişi kendisinin aranan müşteri olduğunu onayladı",
          "condition": {"operator": "matches_intent", "description": "Kişi kendisinin {{first_name}} olduğunu açıkça onayladı ('evet', 'benim', 'buyurun benim' ya da kendi adını söyledi). 'Alo', 'buyurun', 'kimsiniz' onay DEĞİLDİR. Telefonu başkası açtıysa DEĞİLDİR."}}],
        {"type": "llm", "prompt": "Yalnızca şu cümleyi aynen söyle (title={{title}}: Mr ise Bey, Ms ise Hanım): 'Merhaba, ben Freya Bank'ın dijital asistanıyım; görüşmemiz kalite amacıyla kayıt altına alınmaktadır. {{first_name}} Bey ile mi görüşüyorum?' Araç çağırma."})

    ver = api_tool("verify_identity", "/verify_identity", {
        "customer_id": CID,
        "field": {"type": "string", "enum": ["date_of_birth", "phone_last4"], "description": "Hangi soru"},
        "answer": {"type": "string", "description": "date_of_birth için YYYY-AA-GG (yalnız rakamla söylenen tarih gün, ay, yıl sırasıyla okunur; 'on dört Mart seksen sekiz' = 1988-03-14). phone_last4 için dört rakam."}},
        ["field", "answer"], "Müşteri bir güvenlik cevabı verdiğinde HER SEFERİNDE çağır.", post=VERIFY_POST)
    id_task = ("Müşteri adını onayladı. Kimliğini doğrula. Henüz 'tahsilat', 'borç', 'ödeme' kelimelerini ve ürünü söyleme. "
        "Soruları tek tek sor: önce doğum tarihi, sonra dosyadaki telefon numaranızın son dört hanesi. Her cevapta verify_identity çağır. Müşteri kendini düzeltirse son söylediğini kullan. "
        "Toplam üç yanlış cevap kontrolü bitirir; o zaman sonuçtaki talimata uy (mobil uygulama ya da şube, close_call not_verified / failed). "
        "Müşteri cevap vermek istemezse ya da cevap yerine aramanın ne hakkında olduğunu sorarsa bir kez açıkla: 'Bu sorular hesabınızı korumak için; doğrulamadan sonra anlatabilirim.' İkinci ret ya da ikinci böyle soruda teşekkür et, vedalaş ve close_call not_verified / declined çağır. "
        "Müşteri bir insanla görüşmek isterse önce bir kez yardımcı olup olamayacağını sor; ısrar ederse transfer_to_agent queue=general, sonra close_call transferred / human.")
    tr_tool = api_tool("transfer_to_agent", "/transfer_to_agent", {"customer_id": CID,
        "queue": {"type": "string", "enum": ["restructuring", "general", "support"], "description": "Kuyruk"}}, ["queue"],
        "Müşteriyi bir temsilciye aktarır. Yalnızca kurallar aktarma dediğinde çağır.",
        post=POST_GENERIC % ("Aktarma yapılamadı. Müşteriye söyle.", "Aktarma yapıldı. Teşekkür et, vedalaş ve close_call transferred ile çağır."))
    nodes["identity"] = conv("identity", id_task, [ver, tr_tool, close_tool(["not_verified", "transferred"], ["failed", "declined", "human"], "Aramayı kapatır. Yalnızca vedalaştıktan sonra, en sonda çağır.")],
        [CLOSED,
         {"target_node": "get_account", "description": "kimlik doğrulandı", "condition": {"logic": "or", "conditions": [
             {"variable": "verify_identity_response.data.all_verified", "operator": "equals", "operand": "true"},
             {"variable": "verify_identity_response.data.all_verified", "operator": "equals", "operand": "True"}]}}],
        {"type": "tts", "text": "Teşekkür ederim. Güvenlik için birkaç soru soracağım. Doğum tarihinizi söyler misiniz?"}, first_only=True)

    ga = api_tool("get_account", "/get_account", {"customer_id": CID}, [], "Hesap", post=GETACC_POST)
    ga["config"]["maxRetries"] = 2
    nodes["get_account"] = api_node("get_account", "", ga, [always("compute")], mapping=[{"path": "data.products", "variable": "products"}])
    nodes["compute"] = code_node("compute", COMPUTE, [always("negotiate")])

    neg_task = ("Müşteri doğrulandı. Hesap bilgisi (yalnızca bunları kullan):\n- Ürün: {{product_name}} (söylerken: '{{product_name}}')\n- Gecikmiş tutar (tam tutar): {{full_tr}}\n- Gecikme: {{days_late}} gün\n- Alt sınır: {{floor_tr}}\n- Son tarih: {{deadline_tr}}\n- İkna denemesi hakkı: {{max_attempts}}\n"
        "Kurallar:\n"
        "1. Tam tutarı iste. ASLA 'ne kadar ödeyebilirsiniz' diye sorma; tutarı her zaman sen önerirsin.\n"
        "2. Müşterinin söylediği bir tarih ya da tutar asla ret değildir. Tarihi aşağıdaki tabloda bul ve satırda yazanı aynen yap. Müşteri belirsiz bir dönem söylerse ('haftaya', 'ay sonu', 'maaşım yatınca', 'iki hafta sonra') bir kez kesin günü sor; yine söylemezse son tarihi ({{deadline_tr}}) öner.\n"
        "3. Müşteri tam tutarın fazla olduğunu söylerse alt sınırı ({{floor_tr}}) bir kez öner ve kalan tutarın gecikmede kalacağını söyle. Müşteri alt sınır ile tam tutar arasında bir tutar söylerse kabul et.\n"
        "4. Kesin ret (tarih ve tutar söylemeden 'bugün olmaz', 'ödeyemem') ya da cevapsızlık bir ikna denemesi harcar. 1. deneme: {{offer1_date_tr}} günü (tam tutar; müşteri tam tutarın fazla olduğunu söylediyse alt sınır) öner. 2. deneme yalnızca hakkın 2 ise: {{floor_tr}} tutarını {{deadline_tr}} günü öner. Denemeler bitince ya da müşteri son tarihi veya alt sınırı reddederse dur, reddedilen teklifi tekrarlama; teşekkür et, vedalaş, close_call no_promise / refused.\n"
        "5. Hastalık, ailede vefat ya da iş kaybı: kısa bir cümleyle üzüntünü belirt, ikna denemesi yapma, destek ekibine bağlanmayı öner. Kabul ederse transfer_to_agent queue=support, sonra close_call transferred / support. Reddederse teşekkür et, vedalaş, close_call no_promise / hardship.\n"
        "6. 'Zaten ödedim': ödemelerin görünmesinin bir iş günü sürebileceğini söyle, söz alma, teşekkür et, vedalaş, close_call outcome=paid.\n"
        "7. 'Bu borç benim değil', 'böyle bir ürünüm olmadı', 'kapattım/ödedim (geçmişte)': tartışma, söz alma, close_call no_promise / dispute.\n"
        "8. Yeni ödeme planı ya da daha düşük taksit isterse: plan anlatma, transfer_to_agent queue=restructuring, sonra close_call transferred / restructuring.\n"
        "9. İnsanla görüşmek isterse önce bir kez yardımcı olup olamayacağını sor; ısrar ederse transfer_to_agent queue=general, sonra close_call transferred / human.\n"
        "10. Müşteri konuşmak istemediğini iki kez söylerse close_call no_promise / refused.\n"
        "11. Sözü sen kaydetmezsin ve 'kaydedildi' demezsin; müşteri bir gün ve tutarı kabul edince kısaca 'Tamam' de, okuma ve kayıt ayrı adımda yapılır.\n"
        "{{check_msg}}\n"
        "Göreli gün ifadeleri:\n{{rel_table}}\n"
        "Tarih tablosu (müşterinin söylediği günü bul, satırdakini yap):\n{{date_table}}")
    ext = [
        {"name": "proposed_date", "type": "date", "description": "Müşterinin ödeme yapmayı kabul ettiği kesin gün (YYYY-MM-DD). Müşteri en son düzelttiği günü kullan. Belirsiz dönemse boş bırak. Göreli ifadeler: " + "{{rel_table}}", "min_confidence": 0.5},
        {"name": "proposed_amount", "type": "float", "description": "Müşterinin ödemeyi kabul ettiği tutar (TL). Asistanın önerdiği tutarı kabul ettiyse o tutar; tutar söylenmeden bir güne evet dediyse en son konuşulan tutar (önce tam tutar {{full_amount}}).", "min_confidence": 0.5},
        {"name": "agreed", "type": "string", "enum_values": ["yes", "no"], "description": "yes: müşteri bu son mesajında belirli bir günde ödeme yapacağını söyledi ya da asistanın önerdiği günü/tutarı kabul etti. Aksi halde no.", "min_confidence": 0.5}]
    nodes["negotiate"] = conv("negotiate", neg_task, [tr_tool, close_tool(["paid", "transferred", "no_promise"], ["refused", "hardship", "dispute", "restructuring", "human", "support"], "Aramayı kapatır. Yalnızca vedalaştıktan sonra, en sonda çağır.")],
        [CLOSED,
         {"target_node": "check", "description": "müşteri bir gün kabul etti", "condition": {"logic": "or", "conditions": [{"logic": "and", "conditions": [
             {"variable": "agreed", "operator": "equals", "operand": "yes"}, {"variable": "proposed_date", "operator": "is_set"}]}]}}],
        {"type": "tts", "text": "Teşekkür ederim, kimliğiniz doğrulandı. Tahsilat ekibinden gecikmiş bir ödeme için arıyorum. {{product_name}} için {{full_tr}} tutarında, {{days_late}} gündür gecikmiş bir ödeme görünüyor. Bu ödemeyi bugün yapabilir misiniz?"},
        extraction=ext, first_only=True)
    nodes["negotiate"]["loop_prompt"] = ""
    del nodes["negotiate"]["loop_prompt"]

    nodes["check"] = code_node("check", CHECK, [eq("verdict", "ok", "confirm", "uygun"), always("negotiate")])

    conf_task = ("Müşteriye okuduğun sözü onaylatıyorsun: {{confirm_text}} Bu adımda araç çağırma, 'kaydedildi' deme. Müşteri bir soru sorarsa kısaca cevapla ve 'Onaylıyor musunuz?' diye tekrar sor.")
    nodes["confirm"] = conv("confirm", conf_task, [],
        [{"target_node": "write_promise", "description": "müşteri net evet dedi", "condition": {"operator": "matches_intent", "description": "Müşteri okunan ödeme sözünü net olarak onayladı (evet, onaylıyorum, tamam) ve tarihi ya da tutarı değiştirmedi."}},
         {"target_node": "negotiate", "description": "müşteri değiştirmek istiyor", "condition": {"operator": "matches_intent", "description": "Müşteri tarihi ya da tutarı değiştirmek istiyor, başka bir gün/tutar söyledi ya da onaylamadı."}}],
        {"type": "tts", "text": "{{confirm_text}} Onaylıyor musunuz?"})

