        return t
    rec = {"logic": "or", "conditions": [{"variable": "promise_state", "operator": "equals", "operand": "recorded"},
           {"variable": "create_promise_response.data.promise_state", "operator": "equals", "operand": "recorded"}]}
    nodes["write_promise"] = api_node("write_promise", "", promise_tool(),
        [{"target_node": "close_promise", "description": "kaydedildi", "condition": rec}, always("write_retry")])
    nodes["write_retry"] = api_node("write_retry", "", promise_tool(),
        [{"target_node": "close_promise", "description": "kaydedildi", "condition": rec}, always("close_error")])

    def fixed_close(outcome, reason):
