        if reason:
            body["reason"] = {"type": "string", "default": reason}
        return api_tool("close_call", "/close_call", body, ["outcome"], "Kapanış")
    nodes["close_promise"] = api_node("close_promise", "Sözünüz kaydedildi. Bu sözü onaylayan bir kısa mesaj alacaksınız. Kaydedilmiş sözü değiştirmek isterseniz mobil uygulamadan değiştirebilirsiniz. Teşekkür ederim, iyi günler dilerim.",
        fixed_close("promise", None), [always("end")])
    nodes["close_error"] = api_node("close_error", "Üzgünüm, teknik bir sorun nedeniyle sözünüzü kaydedemedim. Teşekkür ederim, iyi günler dilerim.",
        fixed_close("no_promise", "service_error"), [always("end")])
    nodes["end"] = end_node("end")

    for k, n in nodes.items():
        n.setdefault("position", {"x": 0, "y": 0})
    return {"initial_node": "init", "system_prompt": SYS, "nodes": nodes, "global_nodes": {},
            "test_variables": {"customer_id": "c_test", "first_name": "Daniel", "last_name": "Reyes", "title": "Mr", "now": "2026-10-14T11:00"}}

if __name__ == "__main__":
    wf = build()
    json.dump(wf, open(sys.argv[1], "w"), ensure_ascii=False, indent=1)
    print("ok")
